"""Краткое объяснение постановки и связей, отдельное от формальной записки."""
from project_model import AUTHOR,GROUP,TEACHER,DATE,OUT
from document_layout import Writer

GUIDE=OUT/'Защита за 3 минуты и пояснения.docx'
SPEECH=[
 ('0:00–0:30','Моя тема — банковская система. Заказчиком рассматривается руководитель операционного направления. Ему нужно завершать обращения клиентов правильно при ограниченном составе сотрудников. Противоречие состоит в том, что ручная проверка согласованности отнимает тот же труд, который нужен обслуживанию. Уменьшение проверок создаёт риск неверного результата, увеличение — расходует ресурс.'),
 ('0:30–1:00','Общая гипотеза: передать программе повторяемые проверки, учёт и подготовку документов, сохранив решения и ответственность людей. Назначение — подтверждённое завершение обращения с меньшим удельным ручным трудом. Качество определено до выбора функций: тридцать из тридцати обращений завершены верно, критических нарушений нет, труд на обращение уменьшен минимум на двадцать процентов.'),
 ('1:00–1:30','Порог — проектное предложение, которое согласуется до испытаний. Из документов выведены сущности и связи. Из назначения — пять функций: клиентский контекст, карты, переводы, договоры и сведения для контроля. Они раскрыты до пятнадцати листьев. Процессы показывают действия людей и программы, документы, условия успеха и отказа. Каждая программная операция имеет нужное средство.'),
 ('1:30–2:00','Обобщение этих средств дало шесть архитектурных компонентов. Технический проект раскрывает их в одиннадцать модулей с входами, результатами и правилами. Например, проведение перевода требует блокировки обоих счетов, общей фиксации остатков и аудита, безопасного повтора. Детальный компонент показывает конкретные вызовы; словарь и контракты задают типы полей, кодирование, ответы и ошибки.'),
 ('2:00–2:30','Внутренние проверки доказывают отдельные свойства: при двух списаниях по семь тысяч из десяти тысяч проходит только одно; сбой после списания полностью откатывается; кредитный план точно сходится с основной суммой. Но это ещё не доказывает полезность заказчику. Поэтому предусмотрено сравнение полного цикла на одинаковых данных и с теми же исполнителями.'),
 ('2:30–3:00','Для ручного способа и способа с программой учитывается весь труд, включая исправления и сверку. Удельный труд — общий труд, делённый на число верно завершённых обращений. Экономия принимается только при выполнении всех норм. Без базового замера эффект неподтверждён. Подготовлены проект, схемы и методика; фактическую приёмку программного комплекса проводят после реализации.'),
]

def guide_doc():
 w=Writer();w.flow=True
 w.p('Защита банковской системы','Title')
 w.p(f'{AUTHOR} · {GROUP} · {DATE}',indent=0)
 w.h('Как устроена записка')
 for t in [
  'За основу структуры взята исправленная пояснительная записка об аренде автомобилей. Сохранены её семь основных разделов, общие названия подразделов и порядок изложения. Предметные подразделы описывают банковские операции. Проблема, назначение и критерии раскрываются внутри первого раздела, а согласованность моделей — в подразделе 7.8.',
  'Теперь цепь начинается с руководителя, ограниченного труда и противоречия между обслуживанием и ручной проверкой. Затем задаются внешнее назначение и концепция качества. Только после этого выводятся функции, процессы, необходимые программные средства, архитектура, технические задания и проверки.',
  'Расшифровка местами искажена. Выражение в её начале нельзя надёжно восстановить дословно; его смысл раскрыт через вопрос «для чего служит система». По записи нельзя установить, какую именно букву отсутствующего приложения он называл. Поэтому сохранены все шесть основных приложений и добавлены Ж — обеспечение операций, И — словарь и контракты, как в самом подробном принятом образце.',
  'В формальной записке нет утверждения, что программа уже создана или испытана в банке. ГОСТ 19.101–2024 различает документы технического проекта и текст программы. По имеющимся сообщениям предмет защиты — согласованное проектирование и замысел ПМИ. Если преподаватель отдельно потребует демонстрацию работающего комплекса, её нельзя заменить отчётом.',
 ]:w.p(t)
 w.page('Выступление на три минуты',1)
 w.p('Время приблизительное. Прочитай один раз с секундомером; это единственный раздел для произнесения целиком.',size=12,indent=0)
 for time,t in SPEECH:
  w.p(time,size=12,indent=0,before=6,keep=True);w.p(t,size=12,indent=0,after=3).paragraph_format.line_spacing=1.15
 w.page('Что открыть во время ответа',1)
 for title,text in [
  ('Сначала раздел 1 и рисунки Г.4–Г.5','Покажи заказчика, противоречие, назначение и критерии ЦП1–ЦП4. Эти две схемы объясняют смысл всей записки. Начинать с PostgreSQL, таблиц или блокировок не нужно.'),
  ('Затем Б.3, В.4 и приложение Ж','Дерево даёт функции; процесс перевода показывает ОП07–ОП09; Ж связывает лист с операцией, нужным средством, компонентом, модулем и испытанием. Стрелка DFD обозначает данные, а последовательность действий показана BPMN.'),
  ('Далее Г.1, Д.2, Д.7 и приложение И','Г.1 — содержательный состав, Д.2 — его воплощение в М01–М11, Д.7 — подробное устройство проведения. В И можно показать синтаксис конкретной связи: Python-вызов, SQL либо HTTPS JSON UTF-8, поля, результат и отказ.'),
  ('В конце раздел 7 и приложение Е','И01–И23 проверяют предметные свойства и маршруты. И24 сравнивает полный труд ручного способа А и способа Б с программой на 30 одинаковых обращениях. И25 проверяет обоснованность решения, включая отсутствие замера и критический дефект.'),
 ]:w.h(title);w.p(text)
 w.page('Ответы на вероятные вопросы',1)
 for title,text in [
  ('Какую проблему решаете','При ограниченном штате ручная сверка конкурирует за труд с обслуживанием. Нельзя просто убрать проверку; предлагаем автоматизировать повторяемую часть и оценивать весь цикл, включая исправления.'),
  ('Почему критерий — именно 20 процентов','Это проектная норма для согласования, а не обнаруженный факт о банке и не требование ГОСТа. Норма должна быть определена до испытаний. Если заказчик изменяет её или профиль обращений, проект и проверки пересматриваются согласованно.'),
  ('Чья потребность главная','Решение о создании и приёмке принимает руководитель операционного направления. Оператор, клиент, кредитная служба и контролёр имеют частные интересы; их правильные результаты нужны для общего назначения.'),
  ('Что значит удельный труд','u=L/Q: человеко-минуты всех участников, включая помощь, исправления и сверку, делятся на число правильно завершённых обращений. Сравнение допускается при 30 правильных результатах у обоих способов и одинаковых исполнителях.'),
  ('Почему модульных тестов недостаточно','Правильное списание или расчёт графика необходимо, но система может перенести труд на другой участок и не дать выигрыша руководителю. Поэтому проверяется весь процесс А/Б и затем пригодность на согласованном пилоте.'),
  ('Что именно писать программисту','В приложении Д даны задания каждому модулю, в Ж — происхождение и вызываемый обработчик, в И — типы, поля, протоколы и ошибки. Д.7 раскрывает координатор транзакции, серверную функцию и аудит. Код генерации диаграмм — отдельный уже готовый результат.'),
  ('Как проверить развитие','Миграция сохраняет подтверждённый срез, новая формула получает отдельную версию и эталоны, новый отчёт использует прежние факты и права. Повторяются затронутые сценарии и внешние критерии; интерфейсы версионируются.'),
  ('Все ли ГОСТы применены','Весь предоставленный комплект сверён в отдельном реестре. По области применения выбраны конкретные положения. Промышленные модели данных, патентные исследования и эксплуатационные документы не становятся обязательными разделами этой записки только потому, что файлы лежали в папке.'),
 ]:w.h(title);w.p(text)
 w.h('Точные примеры и границы утверждений',1)
 for t in [
  'Перевод: A=10 000, B=1000; перевод 2500 даёт 7500 и 3500. Общая сумма 11 000 сохраняется. При сбое после списания — исходные остатки; повтор даёт прежний факт без второго списания. Два перевода по 7000 из 10 000 дают один успех и один отказ.',
  'План: 120 000 под 12 %, с 01.01.2026, даты 01.02, 01.03, 01.04. Основные части по 40 000; проценты 1223,01; 736,44; 407,67. Для 100,01 под 0 %: 33,33; 33,33; 33,35. Это договорный план; фактическую оплату подтверждает кредитная служба.',
  'Проверка формулы, только условный пример: 180 и 135 человеко-минут на 30 верных обращений дают 6 и 4,5 минуты на обращение, уменьшение 25 %. Эти числа нельзя называть замерами банковской программы.',
 ]:w.p(t)
 for p in w.doc.paragraphs:p.paragraph_format.keep_together=True
 w.save(GUIDE)
 return {'guide':str(GUIDE),'speech_words':sum(len(t.split()) for _,t in SPEECH)}
